const countdown = {
  [Symbol.iterator]() {
    let n = 3;
    return {
      next() {
        return n > 0 ? { value: n--, done: false } : { value: undefined, done: true };
      },
    };
  },
};

[...countdown];                          // [3, 2, 1]
for (const n of countdown) console.log(n); // 3, 2, 1
